      !pIO->Write16(&m_observerRange.end) ||
      !pIO->Write16(&m_observerRange.steps) ||
      !pIO->Write16(&m_reserved2))
    return false;

  icUInt32Number vals = m_observerRange.steps*3;

  if (vals && m_observer)
    if (pIO->WriteFloat32Float(&m_observer[0], vals) != vals)
