CIccMemIO* CIccProfile::GetTagIO(icSignature sig)
{
  IccTagEntry *pEntry = GetTag(sig);

  if (pEntry && m_pAttachIO) {
    CIccMemIO *pIO = new CIccMemIO;

    if (!pIO)
      return NULL;

    if (!pIO->Alloc(pEntry->TagInfo.size)) {
      delete pIO;
      return NULL;
    }

    m_pAttachIO->Seek(pEntry->TagInfo.offset, icSeekSet);
    m_pAttachIO->Read8(pIO->GetData(), pIO->GetLength());
    return pIO;
  }

  return NULL;
}

CIccMemIO* CIccProfile::GetTagIO(icSignature sig)
{
  IccTagEntry *pEntry = GetTag(sig);

  if (pEntry && m_pAttachIO) {
    CIccMemIO *pIO = new CIccMemIO;

    if (!pIO)
      return NULL;

    if (!pIO->Alloc(pEntry->TagInfo.size)) {
      delete pIO;
      return NULL;
    }

    m_pAttachIO->Seek(pEntry->TagInfo.offset, icSeekSet);

    const size_t expected_length = pIO->GetLength();
    size_t read_length = m_pAttachIO->Read8(pIO->GetData(), expected_length);
    if (read_length == expected_length)
      return pIO;
    else {
      delete pIO;
      return NULL;
    }
  }

  return NULL;
}

bool CIccLocalizedUnicode::GetText(std::string &sText)
{
  sText.clear();

  icUInt16Number* str = m_pBuf;
  while (*str) {
    icUInt32Number code32 = 0x0;



    if (*str <= 0xD7FF || *str >= 0xE000) {
      code32 = *str;
      str++;
    }
    else if (*str <= 0xDBFF) {
      icUInt16Number high = (*str - 0xD800) * 0x400;
      icUInt16Number low = *(str + 1) - 0xDC00;
      code32 = (low | high) + 0x10000;
      str += 2;
    }
    else {  
      str++;
      continue;
    }



    if (code32 <= 0x007F) {
      sText += (unsigned char)code32;
    }
    else if (code32 <= 0x07FF) {
      sText += (unsigned char)(((code32 >> 6) & 0x1F) | 0xC0);
      sText += (unsigned char)((code32 & 0x3F) | 0x80);
    }
    else if (code32 <= 0xFFFF) {
      sText += (unsigned char)(((code32 >> 12) & 0x0F) | 0xE0);
      sText += (unsigned char)(((code32 >> 6) & 0x3F) | 0x80);
      sText += (unsigned char)(((code32) & 0x3F) | 0x80);
    }
    else if (code32 <= 0x10FFFF) {
      sText += (unsigned char)(((code32 >> 18) & 0x07) | 0xF0);
      sText += (unsigned char)(((code32 >> 12) & 0x3F) | 0x80);
      sText += (unsigned char)(((code32 >> 6) & 0x3F) | 0x80);
      sText += (unsigned char)(((code32) & 0x3F) | 0x80);
    }
  }

  return true;
}

bool CIccLocalizedUnicode::GetText(std::string &sText)
{
  sText.clear();

  icUInt16Number* str = m_pBuf;
  icUInt16Number *str_end = m_pBuf + m_nLength;
  while ( (str < str_end) && *str ) {
    icUInt32Number code32 = 0x0;



    if (*str <= 0xD7FF || *str >= 0xE000) {
      code32 = *str;
      str++;
    }
    else if (*str <= 0xDBFF) {
      icUInt16Number high = (*str - 0xD800) * 0x400;
      icUInt16Number low = *(str + 1) - 0xDC00;
      code32 = (low | high) + 0x10000;
      str += 2;
    }
    else {  
      str++;
      continue;
    }



    if (code32 <= 0x007F) {
      sText += (unsigned char)code32;
    }
    else if (code32 <= 0x07FF) {
      sText += (unsigned char)(((code32 >> 6) & 0x1F) | 0xC0);
      sText += (unsigned char)((code32 & 0x3F) | 0x80);
    }
    else if (code32 <= 0xFFFF) {
      sText += (unsigned char)(((code32 >> 12) & 0x0F) | 0xE0);
      sText += (unsigned char)(((code32 >> 6) & 0x3F) | 0x80);
      sText += (unsigned char)(((code32) & 0x3F) | 0x80);
    }
    else if (code32 <= 0x10FFFF) {
      sText += (unsigned char)(((code32 >> 18) & 0x07) | 0xF0);
      sText += (unsigned char)(((code32 >> 12) & 0x3F) | 0x80);
      sText += (unsigned char)(((code32 >> 6) & 0x3F) | 0x80);
      sText += (unsigned char)(((code32) & 0x3F) | 0x80);
    }
  }

  return true;
}

void CIccCalculatorFunc::DescribeSequence(std::string &sDescription,
                                       icUInt32Number nOps, SIccCalcOp *op, int nBlanks)
{
  std::string opName;
  std::string funcDesc;

  InsertBlanks(funcDesc, nBlanks);
  funcDesc += "{ ";

  int pos = nBlanks + 2;

  for (icUInt32Number i=0; i<nOps;) {
    if (pos > (nBlanks + 65)) {
      funcDesc += "\n";
      InsertBlanks(funcDesc, nBlanks + 2);
      pos = nBlanks + 2;
    }

    op->Describe(opName, 100); 
    funcDesc += opName;
    funcDesc += " ";
    pos += (int)opName.size() + 1;

    if (op->sig == icSigIfOp) {
      SIccCalcOp *ifop = op;

      if  ((i+1)<nOps && op[1].sig == icSigElseOp) {
        SIccCalcOp *elseop = &op[1];

        icUInt32Number nSubOps = (icUInt32Number)icIntMin(nOps-i, ifop->data.size);
        op++;
        i++;
        funcDesc += "\n";
        DescribeSequence(funcDesc, nSubOps, &op[1], nBlanks+2);
        op += nSubOps;
        i += nSubOps;

        InsertBlanks(funcDesc, nBlanks+2);
        funcDesc += "else\n";



        nSubOps = (icUInt32Number)icIntMin(nOps-i, elseop->data.size);
        DescribeSequence(funcDesc, nSubOps, &op[1], nBlanks+2);
        op += nSubOps;
        i += nSubOps;
      }
      else {
        icUInt32Number remaining = nOps - i - 1;
        icUInt32Number nSubOps = (icUInt32Number)icIntMin(remaining, ifop->data.size);
        funcDesc += "\n";
        DescribeSequence(funcDesc, nSubOps, &op[1], nBlanks+2);
        op += nSubOps;
        i += nSubOps;
      }

      InsertBlanks(funcDesc, nBlanks + 2);
      pos = nBlanks + 2;
    }
    else if (op->sig == icSigSelectOp) {
      op++;
      i++;
      funcDesc += "\n";

      int j, n;

      for (n=0; i+n<nOps; ) {
        if (op[n].sig==icSigCaseOp)
          n++;
        else if (n>1 && op[n].sig==icSigDefaultOp) {
          n++;
          break;
        }
        else
          break;
      }

      int p = n;
      for (j=0; j<n; j++) {
        icUInt32Number nSubOps = (icUInt32Number)icIntMin(nOps-(i+p), op[j].data.size);
        InsertBlanks(funcDesc, nBlanks+2);
        if (op[j].sig==icSigCaseOp)
          funcDesc += "case\n";
        else
          funcDesc += "dflt\n";

        DescribeSequence(funcDesc, nSubOps, &op[p], nBlanks+2);
        p += nSubOps;
      }

      op += p-1;
      i += p-1;

      InsertBlanks(funcDesc, nBlanks + 2);
      pos = nBlanks + 2;
    }
    op++;
    i++;
  }

  funcDesc += "}\n";

  sDescription += funcDesc;
}

