icStatusCMM CIccXformMpe::Begin()
{
  icStatusCMM status;
  status = CIccXform::Begin();

  if (status != icCmmStatOk)
    return status;

  if (!m_pTag) {
    return icCmmStatInvalidLut;
  }


  icUInt16Number inputSamples = GetNumSrcSamples();
  icUInt16Number outputSamples = GetNumDstSamples();
  icUInt16Number xformInputSamples = m_pTag->NumInputChannels();
  icUInt16Number xformOutputSamples = m_pTag->NumOutputChannels();

  if (inputSamples != xformInputSamples || outputSamples != xformOutputSamples)
    return icCmmStatBadXform;

  if (!m_pTag->Begin(icElemInterpLinear, GetProfileCC(), GetConnectionConditions(), GetCmmEnvVarLookup())) {
    return icCmmStatInvalidProfile;
  }

  return icCmmStatOk;
}

bool parse3DTable(icFloatNumber* toLut, icUInt32Number nSizeLut)
  {
    icUInt32Number num = m_sizeLut3D * m_sizeLut3D * m_sizeLut3D;


    if (!m_sizeLut3D || nSizeLut != num*3)
      return false;

    const char* next;
    for (auto n = 0u; n < num && !isEOF();) {
      std::string line = getNextLine();


      if (line[0] == '#' || line.size() == 0)
        continue;
      *toLut++ = (icFloatNumber)atof(line.c_str());
      next = getNext(line.c_str());
      if (!next) {
        printf("Invalid 3DLUT entry\n");
        return false;
      }
      *toLut++ = (icFloatNumber)atof(next);
      next = getNext(next);
      if (!next) {
        printf("Invalid 3DLUT entry\n");
        return false;
      }
      *toLut++ = (icFloatNumber)atof(next);

      n++;
    }
    return true;
  }

