static void pp_mil_k54(fp54_t r, const fp9_t qx, const fp9_t qy, const ep_t p,
		const bn_t a) {
	fp54_t l;
	ep_t _p;
	fp9_t rx, ry, rz, sx, sy, sz, qn;
	int i, len = bn_bits(a) + 1;
	int8_t s[RLC_FP_BITS + 1];

	fp54_null(l);
	ep_null(_p);
	fp9_null(rx);
	fp9_null(ry);
	fp9_null(rz);
	fp9_null(sx);
	fp9_null(sy);
	fp9_null(sz);

	RLC_TRY {
		fp54_new(l);
		ep_new(_p);
		fp9_new(rx);
		fp9_new(ry);
		fp9_new(rz);
		fp9_new(sx);
		fp9_new(sy);
		fp9_new(sz);
		fp9_new(qn);

		fp54_zero(l);
		fp9_copy(rx, qx);
		fp9_copy(ry, qy);
		fp9_set_dig(rz, 1);
#if EP_ADD == BASIC
		ep_neg(_p, p);
#else
		fp_add(_p->x, p->x, p->x);
		fp_add(_p->x, _p->x, p->x);
		fp_neg(_p->y, p->y);
#endif
		fp9_neg(qn, qy);

		bn_rec_naf(s, &len, a, 2);
		for (i = len - 2; i >= 0; i--) {
			fp54_sqr(r, r);
			pp_dbl_k54(l, rx, ry, rz, _p);
			fp54_mul_dxs(r, r, l);
			if (s[i] > 0) {
				pp_add_k54(l, rx, ry, rz, qx, qy, p);
				fp54_mul_dxs(r, r, l);
			}
			if (s[i] < 0) {
				pp_add_k54(l, rx, ry, rz, qx, qn, p);
				fp54_mul_dxs(r, r, l);
			}
		}

		fp54_sqr(l, r);
		fp54_mul(r, r, l);

		fp54_zero(l);
		fp9_copy(sx, rx);
		fp9_copy(sy, ry);
		fp9_copy(sz, rz);
		pp_dbl_k54(l, sx, sy, sz, _p);
		fp54_mul_dxs(r, r, l);
#if EP_ADD == PROJC
		fp9_inv(sz, sz);
		fp9_mul(sx, sx, sz);
		fp9_mul(sy, sy, sz);
#endif
		pp_add_k54(l, rx, ry, rz, sx, sy, p);
		fp54_mul_dxs(r, r, l);
		fp9_frb(rx, qx, 1);
		fp9_frb(ry, qy, 1);
		fp9_zero(sz);
		fp3_set_dig(sz[1], 1);
		fp9_inv(sz, sz);
		fp_copy(sz[0][0], sz[2][2]);
		fp_mul(sz[0][0], sz[0][0], core_get()->fp3_p0[1]);
		fp_mul(sz[0][0], sz[0][0], core_get()->fp3_p1[3]);
		fp_mul(sz[0][0], sz[0][0], core_get()->fp3_p1[0]);
		fp3_mul_nor(sz[0], sz[0]);
		fp3_mul_nor(sz[0], sz[0]);
		fp3_mul_nor(sz[0], sz[0]);
		fp_mul(sz[1][0], sz[0][0], core_get()->fp3_p2[1]);

		for (int i = 0; i < 3; i++) {
			fp3_mul(ry[i], ry[i], sz[0]);
			fp3_mul(rx[i], rx[i], sz[1]);
		}

		fp9_frb(sx, qx, 10);
		fp9_frb(sy, qy, 10);
		for (int j = 0; j < 10; j++) {
			for (int i = 0; i < 3; i++) {
				fp3_mul(sy[i], sy[i], sz[0]);
				fp3_mul(sx[i], sx[i], sz[1]);
			}
		}
		fp9_set_dig(sz, 1);

		pp_add_k54(l, sx, sy, sz, rx, ry, p);
		fp54_mul_dxs(r, r, l);
	}

