		fp9_frb(ry, qy, 1);
		fp9_zero(sz);
		fp3_set_dig(sz[1], 1);
		fp9_inv(sz, sz);
		fp_copy(sz[0][0], sz[2][2]);
		fp_mul(sz[0][0], sz[0][0], core_get()->fp3_p0[1]);
		fp_mul(sz[0][0], sz[0][0], core_get()->fp3_p1[3]);
		fp_mul(sz[0][0], sz[0][0], core_get()->fp3_p1[0]);
		fp3_mul_nor(sz[0], sz[0]);
		fp3_mul_nor(sz[0], sz[0]);
		fp3_mul_nor(sz[0], sz[0]);
		fp_mul(sz[1][0], sz[0][0], core_get()->fp3_p2[1]);

		for (int i = 0; i < 3; i++) {
			fp3_mul(ry[i], ry[i], sz[0]);
			fp3_mul(rx[i], rx[i], sz[1]);
		}

		fp9_frb(sx, qx, 10);
		fp9_frb(sy, qy, 10);
		for (int j = 0; j < 10; j++) {
			for (int i = 0; i < 3; i++) {
				fp3_mul(sy[i], sy[i], sz[0]);
				fp3_mul(sx[i], sx[i], sz[1]);
			}
		}
		fp9_set_dig(sz, 1);

		pp_add_k54(l, sx, sy, sz, rx, ry, p);
		fp54_mul_dxs(r, r, l);
	}

static void pp_mil_k8(fp8_t r, ep2_t *t, ep2_t *q, ep_t *p, int m, bn_t a) {
	fp8_t l;
	ep_t *_p = RLC_ALLOCA(ep_t, m);
	ep2_t *_q = RLC_ALLOCA(ep2_t, m);
	int i, j, len = bn_bits(a) + 1;
	int8_t s[RLC_FP_BITS + 1];

	if (m == 0) {
		return;
	}

	fp8_null(l);

	RLC_TRY {
		fp8_new(l);
		if (_p == NULL || _q == NULL) {
			RLC_THROW(ERR_NO_MEMORY);
		}

		for (j = 0; j < m; j++) {
			ep_null(_p[j]);
			ep2_null(_q[j]);
			ep_new(_p[j]);
			ep2_new(_q[j]);
			ep2_copy(t[j], q[j]);
			ep2_neg(_q[j], q[j]);

#if EP_ADD == BASIC
			ep_neg(_p[j], p[j]);
#else
			fp_neg(_p[j]->x, p[j]->x);
			fp_copy(_p[j]->y, p[j]->y);
#endif
		}

		fp8_zero(l);
		bn_rec_naf(s, &len, a, 2);
		for (i = len - 2; i >= 0; i--) {
			fp8_sqr(r, r);
			for (j = 0; j < m; j++) {
				pp_dbl_k8(l, t[j], t[j], _p[j]);
				fp8_mul(r, r, l);
				if (s[i] > 0) {
					pp_add_k8(l, t[j], q[j], _p[j]);
					fp8_mul_dxs(r, r, l);
				}
				if (s[i] < 0) {
					pp_add_k8(l, t[j], _q[j], _p[j]);
					fp8_mul_dxs(r, r, l);
				}
			}
		}
	}

