        break;
#ifndef MRB_NO_FLOAT
      case MRB_TT_FLOAT:
        cmp = (mrb_float(a_val) > mrb_float(b_val)) ? 1 : (mrb_float(a_val) < mrb_float(b_val)) ? -1 : 0;
        break;
#endif
      case MRB_TT_STRING:
        cmp = mrb_str_cmp(mrb, a_val, b_val);
